INSERT INTO "products" ("id","name","slug","category","description","price","compare_at_price","stock","sizes","colors","image_key","featured","created_at") VALUES(19,'Áo Khoác Nữ Bomber Croptop Chất Dạ Ép 2 Lớp Cao Cấp Thêu Logo Có Cúc Bấm Phong Cách Hàn Quốc Trẻ Trung','ao-khoac-nu-bomber-croptop-da-ep-2-lop-cao-cap-theu-logo-cuc-bam-han-quoc','Áo khoác','Điểm nổi bật không thể bỏ qua! Áo khoác bomber nữ chất dạ ép 2 lớp mềm mại, co giãn tốt, mang lại cảm giác thoải mái và linh hoạt khi vận động. Thiết kế croptop hiện đại, dễ phối đồ, phù hợp với nhiều phong cách thời trang khác nhau. Áo có nhiều màu sắc trẻ trung như đen, xám, bee, đáp ứng sở thích đa dạng của các bạn nữ. Lựa chọn size đa dạng Áo có các size từ S đến XL, phù hợp với nhiều vóc dáng khác nhau. Bạn dễ dàng chọn lựa kích cỡ phù hợp để luôn tự tin khi mặc ra ngoài. Chất liệu & thiết kế - Chất dạ ép 2 lớp mềm mại, co giãn tốt, thấm hút mồ hôi hiệu quả. - Thiết kế croptop năng động, giúp tôn dáng và tạo điểm nhấn cho outfit. - Dễ dàng phối cùng quần jean, chân váy hoặc váy ngắn, đi kèm giày sneaker hoặc boots đều nổi bật. Hướng dẫn bảo quản - Lộn trái áo khi giặt để giữ màu sắc bền đẹp. - Tránh giặt cùng quần áo tối màu. - Sử dụng xà phòng trung tính, không dùng chất tẩy mạnh. - Phơi ngang, tránh phơi trực tiếp dưới nắng gắt. Áo khoác bomber dạ ép 2 lớp croptop nữ – lựa chọn hoàn hảo cho những ai yêu thích sự trẻ trung, năng động và tiện lợi!',175770,369000,67,'["S","M","L","XL"]','["Đen","Trắng","Be","Xám"]','products/f3c622e2-ed1f-4cfa-bb05-d8b7d5084b27.png',1,'2026-10-21 14:05:24');
INSERT INTO "products" ("id","name","slug","category","description","price","compare_at_price","stock","sizes","colors","image_key","featured","created_at") VALUES(20,'Hình xăm Nhật Bản nửa áo giáp prajna Áo thun in 3d nam Mùa hè Bông tai Kẹp Áo thun ngắn tay thông thường','ao-thun-in-3d-nam-hinh-xam-nhat-ban-nua-ao-giap-prajna-ngan-tay','Áo',replace('Áo Thun In 3D Nam Hình Xăm Nhật Bản Nửa Áo Giáp Prajna mang phong cách thời trang cá tính, độc đáo và mạnh mẽ. Thiết kế nổi bật với họa tiết hình xăm Nhật Bản kết hợp hiệu ứng in 3D ấn tượng, tạo nên vẻ ngoài thu hút và khác biệt cho người mặc.\n\nSản phẩm có kiểu dáng áo thun ngắn tay thông thường, phù hợp cho mùa hè nhờ cảm giác thoải mái, dễ mặc và dễ vận động. Thiết kế mang hơi hướng nghệ thuật và phá cách, thích hợp cho những ai yêu thích thời trang cá tính và phong cách nổi bật.\n\nÁo dễ dàng phối cùng quần jeans, quần short, quần jogger hoặc giày sneaker để tạo nên outfit năng động và ấn tượng trong nhiều hoàn cảnh khác nhau.','\n',char(10)),110999,369000,10,'["S","M","L","XL","2XL","3XL"]','["ETC1","ETC2","ETC3"]','products/9b31ff78-a998-4c74-bca8-f074298e92c3.png',1,'2026-10-21 14:09:22');
INSERT INTO "products" ("id","name","slug","category","description","price","compare_at_price","stock","sizes","colors","image_key","featured","created_at") VALUES(21,'Áo thun nam basic in hình mèo hoạt hình MẬP RÕ chứ ai mập mờ chất vải mềm dễ phối đồ hàng ngày','ao-thun-nam-basic-in-hinh-meo-hoat-hinh-map-ro-chu-ai-map-mo','Áo',replace('Áo Thun Nam Basic In Hình Mèo Hoạt Hình “MẬP RÕ Chứ Ai Mập Mờ” mang phong cách thời trang trẻ trung, năng động và hài hước. Thiết kế đơn giản kết hợp họa tiết mèo hoạt hình đáng yêu cùng dòng chữ độc đáo, tạo nên điểm nhấn nổi bật và thể hiện cá tính riêng của người mặc.\n\nSản phẩm sử dụng chất vải mềm mại, mang lại cảm giác dễ chịu và thoải mái khi mặc. Kiểu dáng Basic dễ mặc, phù hợp với nhiều phong cách thời trang từ đơn giản, năng động đến Streetwear cá tính.\n\nVới thiết kế dễ phối đồ, áo có thể kết hợp cùng quần jeans, quần short, quần jogger hoặc quần ống rộng để tạo nên những bộ trang phục trẻ trung, đáng yêu và thời trang.','\n',char(10)),99000,250000,88,'["S","M","L","XL"]','["Đen","Trắng"]','products/19051cbf-b9d5-46a2-9bdf-085891984208.png',1,'2026-10-21 14:14:31');
INSERT INTO "products" ("id","name","slug","category","description","price","compare_at_price","stock","sizes","colors","image_key","featured","created_at") VALUES(22,'Sáng Tạo Ngộ nghĩnh Hình Xăm Cơ Quần Áo Tuyệt Vời Hợp Thời Trang Nam Áo Thun Tay Ngắn 3D Họa Tiết Ba Chiều Độc Đáo','ao-thun-nam-tay-ngan-in-3d-hinh-xam-co-bap-sang-tao-ngo-nghinh','Áo',replace('Loại sản phẩm: Áo thun nam tay ngắn\n\nThiết kế: In 3D họa tiết hình xăm cơ bắp\n\nHọa tiết: Hiệu ứng ba chiều độc đáo, sáng tạo và ngộ nghĩnh\n\nKiểu dáng: Áo thun ngắn tay thời trang\n\nPhong cách: Cá tính, hài hước, mạnh mẽ, phá cách\n\nĐối tượng: Nam giới yêu thích thời trang độc đáo và nổi bật\n\nCông nghệ họa tiết: In hiệu ứng 3D tạo cảm giác chiều sâu\n\nThời tiết: Phù hợp mùa hè và thời tiết ấm\n\nPhù hợp: Đi chơi, dạo phố, du lịch, hoạt động giải trí và sinh hoạt hằng ngày\n\nDễ phối cùng quần jeans, quần short, quần jogger và giày sneaker\n\nƯu điểm: Họa tiết ấn tượng, thiết kế mới lạ, dễ phối đồ và tạo điểm nhấn cá tính','\n',char(10)),101000,279000,6,'["S","M","L","XL"]','["ETZ1D23","ETZ2GH","ETZ1D26"]','products/5c27f137-e371-4c6c-ab06-d84935ffe0db.png',1,'2026-10-21 14:16:18');
INSERT INTO "products" ("id","name","slug","category","description","price","compare_at_price","stock","sizes","colors","image_key","featured","created_at") VALUES(23,'Áo Phông LỐP TRƯỞNG OVERSIZE COTTON 260 GSM Mùa Hè Nam Nữ Unisex MTTEE','ao-phong-lop-truong-oversize-cotton-260gsm-mua-he-nam-nu-unisex-mttee','Áo',replace('Thương hiệu/Mẫu sản phẩm: MTTEE – LỐP TRƯỞNG\n\nLoại sản phẩm: Áo phông nam nữ Unisex\n\nChất liệu: Cotton 260 GSM\n\nĐịnh lượng vải: 260 GSM, dày dặn và đứng form\n\nKiểu dáng: Oversize, form rộng thoải mái\n\nThiết kế: Áo phông tay ngắn trẻ trung\n\nHọa tiết: Dòng chữ “LỐP TRƯỞNG” độc đáo, cá tính\n\nPhong cách: Streetwear, năng động, trẻ trung, hiện đại\n\nĐối tượng: Nam và nữ (Unisex)\n\nThời tiết: Phù hợp mùa hè và nhiều điều kiện thời tiết\n\nPhù hợp: Đi học, đi chơi, dạo phố, du lịch và sinh hoạt hằng ngày\n\nDễ phối cùng quần jeans, quần short, quần cargo, quần ống rộng và giày sneaker\n\nƯu điểm: Chất vải dày dặn, form rộng dễ mặc, họa tiết nổi bật và dễ phối đồ','\n',char(10)),175770,369000,7,'["S","M","L","XL"]','["Đen","Trắng"]','products/504049ff-eb68-4a86-87db-40a04b3f558c.png',1,'2026-10-21 14:18:54');
INSERT INTO "products" ("id","name","slug","category","description","price","compare_at_price","stock","sizes","colors","image_key","featured","created_at") VALUES(24,'Giày Nam Mùa Hè 2026 Phong Cách Mới Thoáng Khí Đế Dày Phù Hợp Với Nam Giày Thể Thao Thông Thường Giày Thể Thao Mũi Tròn Hợp','giay-nam-mua-he-2026-thoang-khi-de-day-the-thao-mui-tron','Giày',replace('Loại sản phẩm: Giày thể thao nam\n\nMẫu sản phẩm: Summer Sneaker 2026\n\nThiết kế: Phong cách mới, trẻ trung, hiện đại\n\nKiểu dáng: Giày thể thao mũi tròn\n\nPhần đế: Thiết kế đế dày thời trang\n\nĐặc tính: Thoáng khí, phù hợp thời tiết mùa hè\n\nPhong cách: Thể thao, năng động, cá tính, hiện đại\n\nĐối tượng: Nam giới yêu thích thời trang thể thao\n\nThời tiết: Phù hợp mùa hè và sử dụng hằng ngày\n\nPhù hợp: Đi học, đi chơi, dạo phố, du lịch và vận động nhẹ\n\nDễ phối cùng quần jeans, quần short, quần jogger, quần kaki và áo thun\n\nƯu điểm: Kiểu dáng thời trang, thiết kế thoáng khí, đế dày cá tính và dễ phối đồ','\n',char(10)),149999,350000,20,'["S","M","L","XL"]','["Đen","Trắng"]','products/e271c984-10c9-469f-9062-96a303cfe193.png',1,'2026-10-21 14:24:58');
CREATE TABLE orders (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  code TEXT NOT NULL UNIQUE,
  customer_name TEXT NOT NULL,
  phone TEXT NOT NULL,
  address TEXT NOT NULL,
  note TEXT NOT NULL DEFAULT '',
  total INTEGER NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, customer_id INTEGER REFERENCES customers(id), voucher_code TEXT, discount INTEGER NOT NULL DEFAULT 0);
